mapper.select:
/* BmsEcMapper.selectEcInPlanDetailList : EC송수신조회 - 반입예정 상세 조회 */

	SELECT
		*
	FROM TB_IFR_ECTOG1_IN_PLAN_DTL
	WHERE 1=1
	AND INTERFACE_ID = #{srchInterfaceId}
	AND INTERFACE_SEQ = #{srchInterfaceSeq}

/* BmsEcMapper.selectEcInPlanDetailRsgList : EC송수신조회 - 반입예정 상세Rsg 조회 */

	SELECT
		*
	FROM TB_IFS_G1TOEC_RSG
	WHERE 1=1
	AND INTERFACE_ID = #{srchInterfaceId}
	AND INTERFACE_SEQ = #{srchInterfaceSeq}

/* BmsEcMapper.selectEcInDetailList : EC송수신조회 - 반입 상세 조회 */

	SELECT
		*
	FROM TB_IFS_G1TOEC_IN_DTL
	WHERE 1=1
	AND INTERFACE_ID = #{srchInterfaceId}
	AND INTERFACE_SEQ = #{srchInterfaceSeq}

/* BmsEcMapper.selectEcEtcDetailList : EC송수신조회 - 통관 상세 조회 */

	SELECT
		*
	FROM TB_IFS_G1TOEC_ETC_DTL
	WHERE 1=1
	AND INTERFACE_ID = #{srchInterfaceId}
	AND INTERFACE_SEQ = #{srchInterfaceSeq}

/* BmsEcMapper.selectEcOutDetailList : EC송수신조회 - 반출 상세 조회 */

	SELECT
		*
	FROM TB_IFS_G1TOEC_OUT_DTL
	WHERE 1=1
	AND INTERFACE_ID = #{srchInterfaceId}
	AND INTERFACE_SEQ = #{srchInterfaceSeq}

/* BmsEcMapper.selectEcInInterfaceId : EC송수신조회 - 반입 인터페이스ID 조회 */
	SELECT
		MAX(INTERFACE_ID)
	FROM TB_IFS_G1TOEC_IN
	WHERE LEFT(INTERFACE_ID, CHARINDEX('-', INTERFACE_ID + '-') - 1) = #{orgInterfaceId}

/* BmsEcMapper.selectEcEtcInterfaceId : EC송수신조회 - 통관 인터페이스ID 조회 */
	SELECT
		MAX(INTERFACE_ID)
	FROM TB_IFS_G1TOEC_ETC
	WHERE LEFT(INTERFACE_ID, CHARINDEX('-', INTERFACE_ID + '-') - 1) = #{orgInterfaceId}

/* BmsEcMapper.selectEcOutPlanInterfaceId : EC송수신조회 - 반출승인 인터페이스ID 조회 */
	SELECT
		MAX(INTERFACE_ID)
	FROM TB_IFS_G1TOEC_OUT_PLAN
	WHERE LEFT(INTERFACE_ID, CHARINDEX('-', INTERFACE_ID + '-') - 1) = #{orgInterfaceId}

/* BmsEcMapper.selectEcOutInterfaceId : EC송수신조회 - 반출 인터페이스ID 조회 */
	SELECT
		MAX(INTERFACE_ID)
	FROM TB_IFS_G1TOEC_OUT
	WHERE LEFT(INTERFACE_ID, CHARINDEX('-', INTERFACE_ID + '-') - 1) = #{orgInterfaceId}

mapper.update:
/* BmsEcMapper.updateEcInResend : EC 반입 재송신 */


	UPDATE TB_IFS_G1TOEC_IN SET
		INTERFACE_ID = #{item.interfaceIdNew}
		, SND_STAT_CD = 'R'
	WHERE LEFT(INTERFACE_ID, CHARINDEX('-', INTERFACE_ID + '-') - 1) = #{item.orgInterfaceId};

	UPDATE TB_IFS_G1TOEC_IN_DTL SET
		INTERFACE_ID = #{item.interfaceIdNew}
	WHERE LEFT(INTERFACE_ID, CHARINDEX('-', INTERFACE_ID + '-') - 1) = #{item.orgInterfaceId};

/* BmsEcMapper.updateEcEtcResend : EC 통관 재송신 */


	UPDATE TB_IFS_G1TOEC_ETC SET
		INTERFACE_ID = #{item.interfaceIdNew}
		, SND_STAT_CD = 'R'
	WHERE LEFT(INTERFACE_ID, CHARINDEX('-', INTERFACE_ID + '-') - 1) = #{item.orgInterfaceId};

	UPDATE TB_IFS_G1TOEC_ETC_DTL SET
		INTERFACE_ID = #{item.interfaceIdNew}
	WHERE LEFT(INTERFACE_ID, CHARINDEX('-', INTERFACE_ID + '-') - 1) = #{item.orgInterfaceId};

/* BmsEcMapper.updateEcOutPlanResend : EC 반출승인 재송신 */


	UPDATE TB_IFS_G1TOEC_OUT_PLAN SET
		INTERFACE_ID = #{item.interfaceIdNew}
		, SND_STAT_CD = 'R'
	WHERE LEFT(INTERFACE_ID, CHARINDEX('-', INTERFACE_ID + '-') - 1) = #{item.orgInterfaceId};

/* BmsEcMapper.updateEcOutResend : EC 반출 재송신 */


	UPDATE TB_IFS_G1TOEC_OUT SET
		INTERFACE_ID = #{item.interfaceIdNew}
		, SND_STAT_CD = 'R'
	WHERE LEFT(INTERFACE_ID, CHARINDEX('-', INTERFACE_ID + '-') - 1) = #{item.orgInterfaceId};

	UPDATE TB_IFS_G1TOEC_OUT_DTL SET
		INTERFACE_ID = #{item.interfaceIdNew}
	WHERE LEFT(INTERFACE_ID, CHARINDEX('-', INTERFACE_ID + '-') - 1) = #{item.orgInterfaceId};
